      "summary": "2026年11月27日（金）、28日（土）、旧東海道品川宿にある海雲寺にて「千躰荒神秋季大祭」が行われます。 海雲寺は、鎌倉時代中期の建長3年（1251）のに海晏寺（臨済宗）の一塔頭として開かれ、慶長元年（1596）に曹洞宗に改められ独立。本堂には本尊十一面観音像を安置しています。また、鎮守として千躰三宝大荒神王を祀っています。",
