      "title": "【品川介護福祉専門学校】7月5日 オープンキャンパス「絵手紙づくり」を行いました！！",
      "summary": "教職員から学校の特色、実際の授業内容について説明があり、在校生の1年生から“授業のここが楽しい”“ここが難しい”などの感想。また、学校のイベントや学校生活について説明がありました。 夏をイメージした「スイカ」「うちわ」、好きな「ねこ」や「くだもの」などを題材に大胆に書いてみるよう！と教員からのアドバイス。それぞれの個性をいかし、素敵な絵手紙を完成することができました。",
