      "title": "ウィラ大井「サマーフェスタ2026」",
      "summary": "2026年7月18日（土）～26日（日）、大井競馬場前のショッピングモール、ウィラ大井にて「サマーフェスタ2026」が開催されます。 7月18日（土）・19日（日）・25日（土）・26日（日）の4日間は、『夏休み 自由研究プロジェクト』として様々な企業とコラボイベントが実施されます 。自由研究のテーマにもおすすめなワークショップや楽しいイベントが盛りだくさんです。",
